__NUXT_JSONP__("/de", (function(a,b,c,d,e){return {data:[{$axios:{request:{},getUri:{},delete:{},get:{},head:{},options:{},post:{},put:{},patch:{},defaults:{headers:{common:{Accept:"application\u002Fjson, text\u002Fplain, *\u002F*","accept-encoding":"gzip, deflate"},delete:{},get:{},head:{},post:{"Content-Type":"application\u002Fx-www-form-urlencoded"},put:{"Content-Type":"application\u002Fx-www-form-urlencoded"},patch:{"Content-Type":"application\u002Fx-www-form-urlencoded"}},baseURL:"http:\u002F\u002F52.198.144.187:81",transformRequest:[{}],transformResponse:[{}],timeout:0,adapter:{},xsrfCookieName:"XSRF-TOKEN",xsrfHeaderName:"X-XSRF-TOKEN",maxContentLength:-1,maxBodyLength:-1,validateStatus:{},transitional:{silentJSONParsing:true,forcedJSONParsing:true,clarifyTimeoutError:false}},interceptors:{request:{handlers:[{fulfilled:{},rejected:void 0,synchronous:false,runWhen:null}]},response:{handlers:[]}},CancelToken:{source:{}},isCancel:{},setBaseURL:{},setHeader:{},setToken:{},onRequest:{},onResponse:{},onRequestError:{},onResponseError:{},onError:{},create:{},$request:{},$delete:{},$get:{},$head:{},$options:{},$post:{},$put:{},$patch:{}},details:{slug:b,pageTitle:c,pageDescription:c,peopleChooseMli:{title:"3 Gründe warum Studenten das MLI gewählt haben",subtitle:"(Mentor Language Institute)",lists:[{image:"\u002Fimages\u002Fhome\u002Fde\u002Fpeople-choose-mli-1.jpg",title:"Hollywood & Westwood",description:"Wir haben Standorte in grossartigen und populären Gegenden von Los Angeles. Studenten können hier nicht nur Englisch lernen, sondern auch Los Angeles geniessen.",read_more:[a]},{image:"\u002Fimages\u002Fhome\u002Fde\u002Fpeople-choose-mli-2.jpg",title:"Kurse am Morgen, Nachmittag und Abend",description:"Wir bieten Kurse am Morgen, Nachmittag und Abend an, für alle, die auf flexible Stundenpläne angewiesen sind.",read_more:[a]},{image:"\u002Fimages\u002Fhome\u002Fde\u002Fpeople-choose-mli-3.jpg",title:"$201 \u002F 1 Woche ～",description:"Sehr gute Lage und erschwingliche Preise! Vergleiche uns mit den Preisen anderer Schulen. Wenn du Informationen zu unseren Studiengebühren möchtest, klicke unten auf Kontaktiere uns.",read_more:[a]}]},highlyRated:"\u002Fimages\u002Fhome\u002Fde\u002Fmli-highly-rated.jpg",courses:{title:"Kurse",lists:[{image:d,title:"ESL programma",subtitle:["Dieses Programm setzt sich aus Unterrichtsteilen mit Schwerpunkt Zuhören\u002FSprechen, Lesen\u002FVokabeln und Grammatik\u002FSchreiben zusammen. Das ESL Programm ist ideal für Studenten, die ihr allgemein ihr Englischniveau verbessern möchten."]},{image:e,title:"TOEFL® Programm",subtitle:["Im MLIs  TOEFL® Programm werfen Studenten einen intensiven Blick auf die erforderlichen Fertigkeiten und Strategien um eine möglichst hohe Punktzahl in den vier Sektionen des onlinebasierten Tests zu erreichen."]},{image:d,title:"Vacation ESL programma (voor een student van korte duur)",subtitle:["Dieses Programm besteht aus Hör-\u002FSprech-, Lese-\u002FVokabular- und Grammatik-\u002FSchreibkursen. \u003Cbr\u003EWir bieten das Vacation ESL-Programm für Studenten an, die für kurze Zeit Englisch lernen möchten."]},{image:e,title:"IELTS™ Programm",subtitle:["IELTS™ ist ein Test, der in Grossbritannien und Australien entwickelt wurde, um die Englischkenntnisse von Studenten zu prüfen. Seit einiger Zeit erfordert die Bewerbung an vielen amerikanischen Universitäten den Nachweis über das Erreichen einer gewissen TOEFL®- oder  IELTS™- Punktzahl.","Das Programm setzt sich aus vier Sektionen zusammen: Zuhören, Sprechen, Lesen und Schreiben. In diesem Kurs lernst du die notwendigen Fertigkeiten\u002FStrategien um eine hohe Punktzahl in jeder der vier Sektionen zu erreichen.","Man sagt IELTS™ wäre einfacher als der TOEFL® Test. Somit ist er das perfekte Programm für alle, denen TOEFL® zu schwierig ist."]},{image:"\u002Fimages\u002Ficons\u002Fmessage.png",title:"Konversationsprogramm",subtitle:["Unser Programm konzentriert sich darauf, deine Konversationsfähigkeiten in Englisch durch fesselnde Aktivitäten und interaktives Lernen zu verbessern! In unseren Konversationskursen erkunden die Schüler eine Vielzahl von Vokabeln, Redewendungen und Idiomen, die deine Gespräche lebendiger machen werden. In unserer CMAR-Klasse kannst du deine Aussprache üben. Durch unterhaltsame Diskussionen, Rollenspiele und Gruppenaktivitäten wirst du an Selbstbewusstsein gewinnen und lernen, dich in sinnvolle Gespräche einzubringen. Unsere erfahrenen Lehrkräfte schaffen eine unterstützende Lernumgebung und begleiten dich auf einer Reise der sprachlichen Entdeckung."]},{image:"\u002Fimages\u002Ficons\u002Fsuitcase.png",title:"Business Englisch plus TOEIC® Programm",subtitle:["Der TOEIC® Test dient als Indikator für die Englischkenntnisse in der Geschäftswelt und wird von verschiedenen Unternehmen und Organisationen rund um den Globus genutzt. Als Ergänzung zum Standard Business Programm, bereitet das TOEIC® Programm Studenten auf den TOEIC® - Zuhören und Lesen Test vor, indem essentielle Vokabeln und Strategien erlernt werden um eine möglichst hohe Punktzahl zu erzielen.","Dieses Programm wird dir helfen deine Englischkenntnisse, wie Vokabular, Lesen, Zuhören und Grammatik, zu verbessern. Durch das Erlernen von Strategien, die dir helfen die richtigen Lösungen zu finden, wirst du in der Lage sein eine hohe Punktzahl zu erreichen."]}]},schedule:"\u002Fimages\u002Fhome\u002Fde\u002Ffree_trial_banner_de.png",link:"\u002Fde\u002Ffreetrial",partnerSchools:{title:"MLI's Partner Universities \u002F Colleges",subtitle:"\"MLI students can enroll at partner universities or colleges after completing certain MLI programs.\""},locationCampus:{title:"Standort \u002F Campus",lists:[{image:"\u002Fimages\u002Fhome\u002Flocation-campus-1.jpg",title:"Westwood Campus",subtitle:"Westwood ist eine lebendige und einzigartige Nachbarschaft im westlichen Teil von Los Angeles. Westwood ist bekannt als Heimat der UCLA. Es ist eine sehr amüsante und populäre Gegend für Studenten., da es viele Geschäfte, Restaurants und sichere Plätze zum Verweilen gibt.",read_more:["\u003Ca href=\"\u002Fde\u002Fwestwood\u002F\"\u003E» MEHR LESEN\u003C\u002Fa\u003E"]},{image:"\u002Fimages\u002Fhome\u002Flocation-campus-2.jpg",title:"Hollywood Campus",subtitle:"Der Hollywood Campus befindet sich gleich neben dem berühmten Chinese Theater.Ausserdem befinden sich auch andere berühmte Filmtheater, gute Restaurants, Geschäfte und Clubs in der immer gut belebten Hollywood Nachbarschaft. ",read_more:["\u003Ca href=\"\u002Fde\u002Fhollywood\u002F\"\u003E» MEHR LESEN\u003C\u002Fa\u003E"]}]},testimonials:{title:"Testimonials von Schülern",seemoreBtn:"Mehr anzeigen",TestimonialLink:"\u002Fde\u002Ftestimonials",readmoreBtn:"Weiterlesen"},dir:"\u002Fhome",path:"\u002Fhome\u002Fde",extension:".json",createdAt:"2026-10-22T16:31:29.576Z",updatedAt:"2025-05-26T12:06:27.782Z"},lang:b}],fetch:{},mutations:void 0}}("\u003Ca href=\"\u002Fde\u002Ffeature\u002F\"\u003E» MEHR LESEN\u003C\u002Fa\u003E","de","Erschwingliche Englisch Sprachschule in Los Angeles | Mentor Language Insitute","\u002Fimages\u002Ficons\u002Fpaste.png","\u002Fimages\u002Ficons\u002Fpen.png")));